\[
 \frac{\sigma\kappa^{23/4}\mu^{3/2}r^{3/2}\sqrt{N_0}
 \max\{N_0\sqrt{\log N_0},T_d\sqrt{\log T_d}\}}
 {\psi_{\min,O_d}\min\{N_0,T_d\}}\to0,
\]
